import re

def is_dynamic(id_value):
    if re.search(r'\d{4,}', id_value):
        return True
    for run in re.findall(r'[0-9a-fA-F]{8,}', id_value):
        if re.search(r'\d', run):
            return True
    return id_value.startswith(('ember', 'react-', ':r'))

function bestLocator(el) {
  if (el.testId) return `getByTestId('${el.testId}')`;
  if (el.role && el.name) return `getByRole('${el.role}', { name: '${el.name}' })`;
  if (el.id && !/\d{4,}/.test(el.id)) return `#${el.id}`;
  if (el.text) return `text=${el.text}`;
  return el.tag;
}
